"""Copper pours (GND on the bottom layer, VCC on the top layer) generated by rasterisation."""
import math
import numpy as np
from PIL import Image, ImageDraw
from scipy import ndimage

PRES = 0.05          # raster pitch (mm)
POUR_CLEAR = 0.30    # pour to other-net copper
EDGE_CLEAR = 0.40    # pour to board edge
THERMAL_W = 0.5      # thermal-relief spoke width
MIN_W = 0.35         # minimum pour feature width (opening)
POUR_NETS = {'bot': 'GND'}

class PourRaster:
    def __init__(self, outline):
        xs = [p[0] for p in outline]; ys = [p[1] for p in outline]
        self.x0, self.y0 = min(xs) - 0.5, min(ys) - 0.5
        self.W = int((max(xs) - min(xs) + 1) / PRES) + 1
        self.H = int((max(ys) - min(ys) + 1) / PRES) + 1
        self.outline = outline
    def px(self, x, y):
        return (x - self.x0) / PRES, (self.H - 1) - (y - self.y0) / PRES
    def xy(self, col, row):
        return self.x0 + col * PRES, self.y0 + (self.H - 1 - row) * PRES
    def blank(self):
        return Image.new('1', (self.W, self.H), 0)
    def draw_copper(self, img, pads, tracks, vias, layer, nets_pred, grow=0.0):
        """Paint copper of `layer` for items whose net satisfies nets_pred, grown by `grow`."""
        dr = ImageDraw.Draw(img)
        g = grow / PRES
        for t in tracks:
            if t['layer'] != layer or not nets_pred(t['net']): continue
            w = t['w'] / PRES + 2 * g
            pts = [self.px(x, y) for (x, y) in t['pts']]
            dr.line(pts, fill=1, width=max(1, int(round(w))), joint='curve')
            for (cx, cy) in pts:
                dr.ellipse([cx - w / 2, cy - w / 2, cx + w / 2, cy + w / 2], fill=1)
        for v in vias:
            if not nets_pred(v['net']): continue
            cx, cy = self.px(v['x'], v['y']); r = 0.3 / PRES + g
            dr.ellipse([cx - r, cy - r, cx + r, cy + r], fill=1)
        for p in pads:
            if layer not in p['layers'] or not nets_pred(p['net']): continue
            cx, cy = self.px(p['x'], p['y'])
            if p['shape'] == 'smd':
                hw, hh = p['size'][0] / 2 / PRES + g, p['size'][1] / 2 / PRES + g
                dr.rectangle([cx - hw, cy - hh, cx + hw, cy + hh], fill=1)
            elif p['shape'] == 'rect':
                hw = p['size'] / 2 / PRES + g
                dr.rectangle([cx - hw, cy - hw, cx + hw, cy + hw], fill=1)
            else:
                r = p['size'] / 2 / PRES + g
                dr.ellipse([cx - r, cy - r, cx + r, cy + r], fill=1)
        return img

def disk(r_px):
    r = int(math.ceil(r_px))
    y, x = np.ogrid[-r:r + 1, -r:r + 1]
    return (x * x + y * y) <= r_px * r_px

def remove_pinches(m, cut=0.10):
    """m is an opened mask.  Its eroded core falls into components; where the dilations of two
    different core components touch, the copper is narrower than MIN_W (a pinch).  Cut along the
    Voronoi boundary between such components (cut width 2*cut + 1 px), clear corner-touching
    pixel pairs, and re-open.  Repeats until stable."""
    r = MIN_W / 2 / PRES
    for _ in range(4):
        core = ndimage.binary_erosion(m, structure=disk(r))
        lab, n = ndimage.label(core, structure=np.ones((3, 3)))
        if n <= 1:
            pass
        else:
            _, idx = ndimage.distance_transform_edt(~core, return_indices=True)
            near = lab[idx[0], idx[1]]
            near[~m] = 0
            b = np.zeros_like(m)
            b[:, :-1] |= (near[:, :-1] != near[:, 1:]) & (near[:, :-1] > 0) & (near[:, 1:] > 0)
            b[:-1, :] |= (near[:-1, :] != near[1:, :]) & (near[:-1, :] > 0) & (near[1:, :] > 0)
            if b.any():
                m = m & ~ndimage.binary_dilation(b, structure=disk(cut / PRES))
        # corner-touching pixel pairs (marching-squares saddles)
        for _ in range(8):
            s1 = m[:-1, :-1] & m[1:, 1:] & ~m[:-1, 1:] & ~m[1:, :-1]
            s2 = m[:-1, 1:] & m[1:, :-1] & ~m[:-1, :-1] & ~m[1:, 1:]
            if not (s1.any() or s2.any()):
                break
            m = m.copy()
            m[:-1, :-1][s1] = False; m[1:, 1:][s1] = False
            m[:-1, 1:][s2] = False; m[1:, :-1][s2] = False
        o = ndimage.binary_opening(m, structure=disk(r))
        if (o == m).all() and not (n > 1 and b.any()):
            return m
        m = o
    return m

def make_pour(d, layer, net, tracks=None, vias=None):
    """Return (raster, mask) of the pour for `net` on `layer` given the layout dict d
    (tracks/vias may be overridden).  Keeps only the largest connected region that touches
    copper of the pour net."""
    tracks = d['tracks'] if tracks is None else tracks
    vias = d['vias'] if vias is None else vias
    R = PourRaster(d['outline'])
    board = R.blank()
    ImageDraw.Draw(board).polygon([R.px(x, y) for (x, y) in d['outline']], fill=1)
    board = np.array(board, bool)
    board = ndimage.binary_erosion(board, structure=disk(EDGE_CLEAR / PRES))
    other = R.blank()
    R.draw_copper(other, d['pads'], tracks, vias, layer, lambda n: n != net, grow=POUR_CLEAR)
    # holes of other nets (drill + annular) are inside their pads already; NC pads (net None) count as other
    free = board & ~np.array(other, bool)
    # thermal reliefs on the pour net's own pads: clearance ring around every pad, bridged by spokes
    # (4 diagonal spokes on through-hole pads, 4 axial spokes on SMD pads) so the pads stay solderable
    ring = R.blank(); spokes = R.blank()
    dr_r = ImageDraw.Draw(ring); dr_s = ImageDraw.Draw(spokes)
    g = POUR_CLEAR / PRES
    for p in d['pads']:
        if layer not in p['layers'] or p['net'] != net: continue
        cx, cy = R.px(p['x'], p['y'])
        if p['shape'] == 'smd':
            hw, hh = p['size'][0] / 2 / PRES, p['size'][1] / 2 / PRES
            dr_r.rectangle([cx - hw - g, cy - hh - g, cx + hw + g, cy + hh + g], fill=1)
            L = max(hw, hh) + g + 0.3 / PRES; angles = (0, 90, 180, 270)
        else:
            r = p['size'] / 2 / PRES
            if p['shape'] == 'rect':
                dr_r.rectangle([cx - r - g, cy - r - g, cx + r + g, cy + r + g], fill=1)
            else:
                dr_r.ellipse([cx - r - g, cy - r - g, cx + r + g, cy + r + g], fill=1)
            L = r * 1.42 + g + 0.3 / PRES; angles = (45, 135, 225, 315)
        for a in angles:
            ex, ey = cx + L * math.cos(math.radians(a)), cy - L * math.sin(math.radians(a))
            dr_s.line([(cx, cy), (ex, ey)], fill=1, width=int(round(THERMAL_W / PRES)))
    free = (free & ~np.array(ring, bool)) | (np.array(spokes, bool) & board & ~np.array(other, bool))
    # remove slivers: opening, then cut the pinches an opening cannot remove (two locally wide
    # areas whose disks merely touch), so that every neck of the pour is at least MIN_W wide
    free = ndimage.binary_opening(free, structure=disk(MIN_W / 2 / PRES))
    free = remove_pinches(free)
    # own copper (pads/tracks/vias of the pour net) merges with the pour
    own = R.blank()
    R.draw_copper(own, d['pads'], tracks, vias, layer, lambda n: n == net)
    own = np.array(own, bool)
    lab, nl = ndimage.label(free | own)          # 4-connectivity: diagonal pixel joins do not count
    if nl == 0:
        return R, np.zeros_like(free)
    # keep every component that touches copper of the pour net (they are all tied together
    # through the net's own tracks, vias and pads); drop isolated islands
    keep = np.zeros_like(free)
    for l in range(1, nl + 1):
        m = lab == l
        if (m & own).sum() * PRES * PRES >= 0.05 and (m & free).sum() * PRES * PRES > 1.0:
            keep |= m
    mask = keep & free
    return R, mask

def pour_cells(R, mask, ij_func, NX, NY, shrink=0.2):
    """Router cells whose centre lies inside the pour eroded by `shrink` (safe seed cells)."""
    m = ndimage.binary_erosion(mask, structure=disk(shrink / PRES))
    cells = set()
    rows, cols = np.nonzero(m)
    for r, c in zip(rows[::1], cols[::1]):
        x, y = R.xy(c, r)
        i, j = ij_func(x, y)
        if 0 <= i < NX and 0 <= j < NY:
            # accept only if the cell centre is really inside
            cc, rr = R.px(i * 0 + x, y)  # dummy
            cells.add((i, j))
    # verify centres
    out = set()
    for (i, j) in cells:
        pass
    return cells

def cells_inside(R, mask, xy_func, NX, NY, shrink=0.2):
    m = ndimage.binary_erosion(mask, structure=disk(shrink / PRES))
    out = set()
    for i in range(NX):
        for j in range(NY):
            x, y = xy_func(i, j)
            c, r = R.px(x, y)
            c, r = int(round(c)), int(round(r))
            if 0 <= c < R.W and 0 <= r < R.H and m[r, c]:
                out.add((i, j))
    return out

def scanlines(R, mask, ap=0.1):
    """Convert the mask into horizontal stroke segments (x1, y, x2) in mm for Gerber output.
    Strokes are inset by ap/2 so the round aperture stays inside the mask."""
    segs = []
    inset = ap / 2
    for r in range(R.H):
        row = mask[r]
        if not row.any(): continue
        dif = np.diff(np.concatenate(([0], row.astype(np.int8), [0])))
        starts = np.nonzero(dif == 1)[0]; ends = np.nonzero(dif == -1)[0] - 1
        y = R.xy(0, r)[1]
        for s, e in zip(starts, ends):
            x1, x2 = R.xy(s, r)[0] + inset, R.xy(e, r)[0] - inset
            if x2 - x1 >= 0:
                segs.append((x1, y, x2))
    return segs

def pour_outline_polygons(R, mask):
    """Approximate outline polygons (for KiCad zone) - we simply return the board outline; KiCad refills."""
    return None


def rdp(pts, tol):
    """Ramer-Douglas-Peucker simplification of a closed polyline (list of (x, y))."""
    if len(pts) < 4:
        return pts
    def simplify(seg):
        a, b = seg[0], seg[-1]
        if len(seg) < 3:
            return seg
        ax, ay = a; bx, by = b
        dx, dy = bx - ax, by - ay
        L = math.hypot(dx, dy)
        best, idx = 0.0, 0
        for i in range(1, len(seg) - 1):
            px, py = seg[i]
            d = abs(dy * px - dx * py + bx * ay - by * ax) / L if L > 1e-12 else math.hypot(px - ax, py - ay)
            if d > best:
                best, idx = d, i
        if best > tol:
            return simplify(seg[:idx + 1])[:-1] + simplify(seg[idx:])
        return [a, b]
    # split the ring at the farthest point from pts[0] so RDP has two open halves
    far = max(range(len(pts)), key=lambda i: (pts[i][0] - pts[0][0]) ** 2 + (pts[i][1] - pts[0][1]) ** 2)
    h1 = simplify(pts[:far + 1]); h2 = simplify(pts[far:] + [pts[0]])
    out = h1[:-1] + h2[:-1]
    return out

def mask_polygons(R, mask, tol=0.03):
    """Vectorise the pour mask into (outer, [holes]) polygon lists in mm using matplotlib contours."""
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    pad = np.pad(mask.astype(np.float32), 1)
    fig, ax = plt.subplots()
    cs = ax.contour(pad, levels=[0.5])
    plt.close(fig)
    loops = []
    for coll in (cs.allsegs[0] if hasattr(cs, 'allsegs') else []):
        seg = [(R.x0 + (c - 1) * PRES, R.y0 + (R.H - 1 - (r - 1)) * PRES) for (c, r) in coll]
        if len(seg) >= 4:
            loops.append(rdp(seg, tol))
    # classify: a loop inside an odd number of other loops is a hole
    def inside(pt, poly):
        x, y = pt; ins = False; n = len(poly)
        for i in range(n):
            x1, y1 = poly[i]; x2, y2 = poly[(i + 1) % n]
            if (y1 > y) != (y2 > y):
                xi = x1 + (y - y1) * (x2 - x1) / (y2 - y1)
                if x < xi: ins = not ins
        return ins
    outers, holes = [], []
    for i, lp in enumerate(loops):
        depth = sum(1 for j, o in enumerate(loops) if j != i and inside(lp[0], o))
        (holes if depth % 2 else outers).append(lp)
    return outers, holes
